using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(200)]
    public string Title { get; set; } = "";

    [Required]
    public string Category { get; set; } = "";

    public string Description { get; set; } = "";

    [Required, MinLength(1, ErrorMessage = "Add at least one ingredient.")]
    public List<string> Ingredients { get; set; } = new();

    [Required, MinLength(1, ErrorMessage = "Add at least one step.")]
    public List<string> Steps { get; set; } = new();

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(200, ErrorMessage = "Title must be 200 characters or fewer.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();

    public static readonly string[] Categories =
        ["Breakfast", "Lunch", "Dinner", "Desserts", "Snacks"];

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy buttermilk pancakes perfect for a weekend breakfast.",
                Ingredients = ["2 cups flour", "2 tbsp sugar", "1 tbsp baking powder", "1/2 tsp salt", "2 eggs", "1 1/2 cups buttermilk", "1/4 cup melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, buttermilk, and melted butter.", "Combine wet and dry ingredients until just mixed.", "Pour 1/4 cup batter onto a hot greased griddle.", "Cook until bubbles form, then flip and cook until golden."],
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple and delicious avocado toast with a twist.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Red pepper flakes", "Salt and pepper", "2 eggs (optional)"],
                Steps = ["Toast the bread until golden.", "Mash avocado with lemon juice, salt, and pepper.", "Spread avocado on toast.", "Top with red pepper flakes and a fried egg if desired."],
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Description = "A classic Caesar salad with homemade dressing.",
                Ingredients = ["1 head romaine lettuce", "1/2 cup croutons", "1/4 cup parmesan cheese", "2 tbsp olive oil", "1 tbsp lemon juice", "1 tsp Dijon mustard", "1 clove garlic"],
                Steps = ["Wash and chop romaine lettuce.", "Whisk olive oil, lemon juice, mustard, and minced garlic.", "Toss lettuce with dressing.", "Top with croutons and shaved parmesan."],
                AverageRating = 4.0, RatingCount = 6
            },
            new()
            {
                Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch",
                Description = "A hearty wrap filled with grilled chicken and fresh vegetables.",
                Ingredients = ["2 chicken breasts", "4 flour tortillas", "1 cup mixed greens", "1 tomato, diced", "1/2 cup shredded cheese", "Ranch dressing"],
                Steps = ["Season and grill chicken until cooked through.", "Slice chicken into strips.", "Warm tortillas on the grill.", "Layer greens, chicken, tomato, cheese, and dressing.", "Roll up tightly and serve."],
                AverageRating = 4.3, RatingCount = 10
            },
            new()
            {
                Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and hearty Italian meat sauce over pasta.",
                Ingredients = ["1 lb ground beef", "1 lb spaghetti", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic", "2 tbsp olive oil", "1 tsp Italian seasoning", "Salt and pepper"],
                Steps = ["Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and cook until browned.", "Stir in tomatoes and seasoning, simmer 20 minutes.", "Serve sauce over spaghetti with parmesan."],
                AverageRating = 4.7, RatingCount = 20
            },
            new()
            {
                Id = 6, Title = "Grilled Salmon", Category = "Dinner",
                Description = "Perfectly grilled salmon with a lemon-herb glaze.",
                Ingredients = ["4 salmon fillets", "2 tbsp olive oil", "2 tbsp lemon juice", "1 tsp garlic powder", "1 tsp dried dill", "Salt and pepper"],
                Steps = ["Mix olive oil, lemon juice, garlic powder, and dill.", "Brush mixture over salmon fillets.", "Preheat grill to medium-high heat.", "Grill salmon 4-5 minutes per side.", "Serve with lemon wedges."],
                AverageRating = 4.6, RatingCount = 15
            },
            new()
            {
                Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Chewy chocolate chip cookies that everyone loves.",
                Ingredients = ["2 1/4 cups flour", "1 cup butter, softened", "3/4 cup sugar", "3/4 cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
                Steps = ["Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheet.", "Bake at 375°F for 9-11 minutes."],
                AverageRating = 4.8, RatingCount = 25
            },
            new()
            {
                Id = 8, Title = "Tiramisu", Category = "Desserts",
                Description = "Classic Italian no-bake dessert with coffee and mascarpone.",
                Ingredients = ["6 egg yolks", "3/4 cup sugar", "1 1/4 cups mascarpone", "2 cups heavy cream", "2 cups espresso, cooled", "3 tbsp coffee liqueur", "24 ladyfingers", "Cocoa powder"],
                Steps = ["Whisk egg yolks and sugar over double boiler until thick.", "Remove from heat, fold in mascarpone.", "Whip cream to stiff peaks and fold into mascarpone mixture.", "Mix espresso and liqueur, dip ladyfingers briefly.", "Layer ladyfingers and cream in a dish.", "Refrigerate 4+ hours, dust with cocoa before serving."],
                AverageRating = 4.9, RatingCount = 18
            },
            new()
            {
                Id = 9, Title = "Trail Mix Energy Bites", Category = "Snacks",
                Description = "No-bake energy bites perfect for on-the-go snacking.",
                Ingredients = ["1 cup oats", "1/2 cup peanut butter", "1/3 cup honey", "1/2 cup chocolate chips", "1/4 cup dried cranberries", "1/4 cup sunflower seeds"],
                Steps = ["Mix all ingredients in a bowl.", "Refrigerate for 30 minutes.", "Roll into 1-inch balls.", "Store in the fridge for up to a week."],
                AverageRating = 4.1, RatingCount = 7
            },
            new()
            {
                Id = 10, Title = "Guacamole", Category = "Snacks",
                Description = "Fresh homemade guacamole with a kick.",
                Ingredients = ["3 ripe avocados", "1 lime, juiced", "1/2 tsp salt", "1/2 cup onion, diced", "1 jalapeño, minced", "2 tbsp cilantro", "1 tomato, diced"],
                Steps = ["Mash avocados in a bowl.", "Stir in lime juice and salt.", "Mix in onion, jalapeño, cilantro, and tomato.", "Serve immediately with tortilla chips."],
                AverageRating = 4.4, RatingCount = 14
            }
        };
    }

    public List<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r =>
                r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is null || stars < 1 || stars > 5) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _recipes.Max(r => r.Id) + 1,
                Title = submission.Title,
                Category = submission.Category,
                Description = "",
                Ingredients = submission.Ingredients
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList(),
                Steps = submission.Steps
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList()
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService Recipes

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hoverRating ?? currentRating) ? "filled" : "")"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => hoverRating = star"
                  @onmouseout="() => hoverRating = null"
                  role="button"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                ★
            </span>
        }
    </div>
    <span class="rating-info">
        @if (submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        @AverageRating.ToString("0.0") avg (@RatingCount ratings)
    </span>
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int currentRating;
    private int? hoverRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        if (submitted) return;
        currentRating = stars;
        Recipes.AddRating(RecipeId, stars);

        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin: 1rem 0;
}

.stars {
    display: flex;
    gap: 0.15rem;
}

.star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover {
    transform: scale(1.2);
}

.star.filled {
    color: #f5a623;
}

.rating-info {
    font-size: 0.9rem;
    color: #666;
}

