                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="mb-2">
                            <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                            <small class="text-muted">@recipe.AverageRating.ToString("0.0") (@recipe.RatingCount)</small>
                        </div>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-2">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        var titleCase = System.Globalization.CultureInfo.CurrentCulture.TextInfo
            .ToTitleCase(CategoryName.ToLower());
        CategoryName = titleCase;
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

