toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@using RecipeShare.Components.Shared
@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id"
                AverageRating="recipe.AverageRating"
                RatingCount="recipe.RatingCount" />

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>🧾 Ingredients</h3>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>

        <div class="col-md-7">
            <h3>👨‍🍳 Steps</h3>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="category/@recipe.Category.ToLower()" class="btn btn-outline-secondary mt-4">
        ← Back to @recipe.Category
    </a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@submission.Title</strong>" has been added.
        <a href="recipe/@newRecipeId">View it here</a>.
    </div>
    <a href="submit" class="btn btn-primary" @onclick="Reset">Submit Another</a>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="submission.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => submission.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="submission.Category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.Categories)
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => submission.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="submission.Ingredients" class="form-control" rows="5"
                           placeholder="One ingredient per line&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => submission.Ingredients" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="submission.Steps" class="form-control" rows="5"
                           placeholder="One step per line&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Combine and bake" />
            <ValidationMessage For="() => submission.Steps" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;
    private int newRecipeId;

    private void HandleSubmit()
    {
        var recipe = Recipes.AddRecipe(submission);
        newRecipeId = recipe.Id;
        submitted = true;
    }

    private void Reset()
    {
        submission = new();
        submitted = false;
    }
}

